package org.example;

import javafx.application.Application;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.stage.Stage;

public class CuraVitaApp extends Application {

    @Override
    public void start(Stage primaryStage) throws Exception {
        FXMLLoader loader = new FXMLLoader(getClass().getResource("/fxml/Accueil.fxml"));
        Parent root = loader.load();
        Scene scene = new Scene(root, 1400, 900);
        scene.getStylesheets().add(getClass().getResource("/css/styles.css").toExternalForm());

        primaryStage.setTitle("CuraVita - Gestion de Pharmacie");
        primaryStage.setScene(scene);
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

package org.example;

import javafx.application.Application;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.stage.Stage;

public class CuraVitaApp extends Application {

    @Override
    public void start(Stage primaryStage) throws Exception {
        FXMLLoader loader = new FXMLLoader(getClass().getResource("/fxml/Accueil.fxml"));
        Parent root = loader.load();
        Scene scene = new Scene(root);
        scene.getStylesheets().add(getClass().getResource("/css/styles.css").toExternalForm());

        primaryStage.setTitle("CuraVita - Gestion de Pharmacie");
        primaryStage.setScene(scene);
        primaryStage.setFullScreen(true);
        primaryStage.setFullScreenExitHint("Press ESC to exit fullscreen");
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

package org.example.util;

import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.PDPageContentStream;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.pdmodel.font.PDType1Font;
import org.example.model.ResponseQuestion;

import java.io.IOException;
import java.nio.file.Path;
import java.time.format.DateTimeFormatter;
import java.util.List;

public class PdfExportUtil {
    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");

    public static void exportResponseQuestions(List<ResponseQuestion> responses, Path outputPath) throws IOException {
        try (PDDocument document = new PDDocument()) {
            PDPage page = new PDPage(PDRectangle.A4);
            document.addPage(page);

            float margin = 40;
            float y = page.getMediaBox().getHeight() - margin;
            float leading = 14;

            try (PDPageContentStream content = new PDPageContentStream(document, page)) {
                content.setFont(PDType1Font.HELVETICA_BOLD, 16);
                content.beginText();
                content.newLineAtOffset(margin, y);
                content.showText("CuraVita - Response Questions");
                content.endText();

                y -= leading * 2;
                content.setFont(PDType1Font.HELVETICA, 10);

                for (ResponseQuestion response : responses) {
                    if (y < margin + leading * 4) {
                        content.close();
                        page = new PDPage(PDRectangle.A4);
                        document.addPage(page);
                        y = page.getMediaBox().getHeight() - margin;
                    }

                    String line = String.format("#%d | Q: %s | Auteur: %s | Role: %s | Statut: %s | %s",
                            response.getId(),
                            safe(response.getQuestionObjet()),
                            response.getAuteurType() != null ? response.getAuteurType().getLabel() : "",
                            response.getReponseRole() != null ? response.getReponseRole().getLabel() : "",
                            response.getImpactStatut() != null ? response.getImpactStatut().getLabel() : "",
                            response.getCreatedAt() != null ? response.getCreatedAt().format(DATE_FORMAT) : "");

                    content.beginText();
                    content.newLineAtOffset(margin, y);
                    content.showText(truncate(line, 110));
                    content.endText();

                    y -= leading;
                    content.beginText();
                    content.newLineAtOffset(margin, y);
                    content.showText("Reponse: " + truncate(safe(response.getReponseText()), 120));
                    content.endText();

                    y -= leading * 1.5f;
                }
            }

            document.save(outputPath.toFile());
        }
    }

    private static String safe(String value) {
        return value == null ? "" : value;
    }

    private static String truncate(String value, int max) {
        if (value.length() <= max) {
            return value;
        }
        return value.substring(0, max - 3) + "...";
    }
}

package org.example.util;

import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.PDPageContentStream;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.pdmodel.font.PDType1Font;
import org.example.model.ResponseQuestion;

import java.io.IOException;
import java.nio.file.Path;
import java.time.format.DateTimeFormatter;
import java.util.List;

public class PdfExportUtil {
    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");

    public static void exportResponseQuestions(List<ResponseQuestion> responses, Path outputPath) throws IOException {
        try (PDDocument document = new PDDocument()) {
            PDPage page = new PDPage(PDRectangle.A4);
            document.addPage(page);

            float margin = 40;
            float y = page.getMediaBox().getHeight() - margin;
            float leading = 14;

            PDPageContentStream content = new PDPageContentStream(document, page);
            try {
                content.setFont(PDType1Font.HELVETICA_BOLD, 16);
                content.beginText();
                content.newLineAtOffset(margin, y);
                content.showText("CuraVita - Response Questions");
                content.endText();

                y -= leading * 2;
                content.setFont(PDType1Font.HELVETICA, 10);

                for (ResponseQuestion response : responses) {
                    if (y < margin + leading * 4) {
                        content.close();
                        page = new PDPage(PDRectangle.A4);
                        document.addPage(page);
                        y = page.getMediaBox().getHeight() - margin;
                        content = new PDPageContentStream(document, page);
                        content.setFont(PDType1Font.HELVETICA, 10);
                    }

                    String line = String.format("#%d | Q: %s | Auteur: %s | Role: %s | Statut: %s | %s",
                            response.getId(),
                            safe(response.getQuestionObjet()),
                            response.getAuteurType() != null ? response.getAuteurType().getLabel() : "",
                            response.getReponseRole() != null ? response.getReponseRole().getLabel() : "",
                            response.getImpactStatut() != null ? response.getImpactStatut().getLabel() : "",
                            response.getCreatedAt() != null ? response.getCreatedAt().format(DATE_FORMAT) : "");

                    content.beginText();
                    content.newLineAtOffset(margin, y);
                    content.showText(truncate(line, 110));
                    content.endText();

                    y -= leading;
                    content.beginText();
                    content.newLineAtOffset(margin, y);
                    content.showText("Reponse: " + truncate(safe(response.getReponseText()), 120));
                    content.endText();

                    y -= leading * 1.5f;
                }
            } finally {
                content.close();
            }

            document.save(outputPath.toFile());
        }
    }

    private static String safe(String value) {
        return value == null ? "" : value;
    }

    private static String truncate(String value, int max) {
        if (value.length() <= max) {
            return value;
        }
        return value.substring(0, max - 3) + "...";
    }
}

package org.example.model;

public class Question {
    private int id;
    private String objet;

    public Question() {
    }

    public Question(int id, String objet) {
        this.id = id;
        this.objet = objet;
    }

    public int getId() {
        return id;
    }

    public void setId(int id) {
        this.id = id;
    }

    public String getObjet() {
        return objet;
    }

    public void setObjet(String objet) {
        this.objet = objet;
    }
}

package org.example.model;

public class Question {
    private int id;
    private String objet;
    private String typeTicket;
    private String priorite;
    private String statut;
    private java.time.LocalDateTime createdAt;

    public Question() {
    }

    public Question(int id, String objet) {
        this.id = id;
        this.objet = objet;
    }

    public Question(int id, String objet, String typeTicket, String priorite, String statut, java.time.LocalDateTime createdAt) {
        this.id = id;
        this.objet = objet;
        this.typeTicket = typeTicket;
        this.priorite = priorite;
        this.statut = statut;
        this.createdAt = createdAt;
    }

    public int getId() {
        return id;
    }

    public void setId(int id) {
        this.id = id;
    }

    public String getObjet() {
        return objet;
    }

    public void setObjet(String objet) {
        this.objet = objet;
    }

    public String getTypeTicket() {
        return typeTicket;
    }

    public void setTypeTicket(String typeTicket) {
        this.typeTicket = typeTicket;
    }

    public String getPriorite() {
        return priorite;
    }

    public void setPriorite(String priorite) {
        this.priorite = priorite;
    }

    public String getStatut() {
        return statut;
    }

    public void setStatut(String statut) {
        this.statut = statut;
    }

    public java.time.LocalDateTime getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(java.time.LocalDateTime createdAt) {
        this.createdAt = createdAt;
    }
}

package org.example.service;

import org.example.model.Question;
import org.example.util.DatabaseUtil;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;
import java.util.HashSet;
import java.util.Set;

public class QuestionService {
    private String userFkColumn;

    public List<Question> getAllQuestions() {
        List<Question> questions = new ArrayList<>();
        String sql = "SELECT id_question, objet, type_ticket, priorite, statut, created_at FROM question ORDER BY id_question DESC";

        try (Connection conn = DatabaseUtil.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql);
             ResultSet rs = stmt.executeQuery()) {

            while (rs.next()) {
                java.sql.Timestamp createdAt = rs.getTimestamp("created_at");
                questions.add(new Question(
                        rs.getInt("id_question"),
                        rs.getString("objet"),
                        rs.getString("type_ticket"),
                        rs.getString("priorite"),
                        rs.getString("statut"),
                        createdAt != null ? createdAt.toLocalDateTime() : null
                ));
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }

        return questions;
    }

    public boolean createQuestion(String typeTicket,
                                  String objet,
                                  String description,
                                  String priorite,
                                  String statut,
                                  String fileName,
                                  String filePath,
                                  String fileType,
                                  Integer fileSize,
                                  java.time.LocalDateTime createdAt,
                                  Integer utilisateurId) {
        String sql = "INSERT INTO question (type_ticket, objet, description, priorite, statut, file_name, file_path, file_type, file_size, created_at, "
                + getUserFkColumn() + ") " +
                "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";

        try (Connection conn = DatabaseUtil.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, typeTicket);
            stmt.setString(2, objet);
            stmt.setString(3, description);
            stmt.setString(4, priorite);
            stmt.setString(5, statut);
            stmt.setString(6, fileName);
            stmt.setString(7, filePath);
            stmt.setString(8, fileType);
            if (fileSize == null) {
                stmt.setNull(9, java.sql.Types.INTEGER);
            } else {
                stmt.setInt(9, fileSize);
            }
            stmt.setTimestamp(10, java.sql.Timestamp.valueOf(createdAt));
            if (utilisateurId == null) {
                stmt.setNull(11, java.sql.Types.INTEGER);
            } else {
                stmt.setInt(11, utilisateurId);
            }
            return stmt.executeUpdate() > 0;
        } catch (SQLException e) {
            e.printStackTrace();
        }
        return false;
    }

    private String getUserFkColumn() {
        if (userFkColumn != null) {
            return userFkColumn;
        }
        String resolved = "id_utilisateur_id";
        try (Connection conn = DatabaseUtil.getConnection();
             ResultSet rs = conn.getMetaData().getColumns(conn.getCatalog(), null, "question", null)) {
            Set<String> columns = new HashSet<>();
            while (rs.next()) {
                columns.add(rs.getString("COLUMN_NAME").toLowerCase());
            }
            if (columns.contains("id_utilisateur")) {
                resolved = "id_utilisateur";
            }
        } catch (SQLException e) {
            // keep default
        }
        userFkColumn = resolved;
        return userFkColumn;
    }
}

package org.example.service;

import org.example.model.Question;
import org.example.util.DatabaseUtil;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;
import java.util.HashSet;
import java.util.Set;

public class QuestionService {
    private String userFkColumn;
    private String responseQuestionFkColumn;

    public List<Question> getAllQuestions() {
        List<Question> questions = new ArrayList<>();
        String sql = "SELECT id_question, objet, type_ticket, priorite, statut, created_at FROM question ORDER BY id_question DESC";

        try (Connection conn = DatabaseUtil.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql);
             ResultSet rs = stmt.executeQuery()) {

            while (rs.next()) {
                java.sql.Timestamp createdAt = rs.getTimestamp("created_at");
                questions.add(new Question(
                        rs.getInt("id_question"),
                        rs.getString("objet"),
                        rs.getString("type_ticket"),
                        rs.getString("priorite"),
                        rs.getString("statut"),
                        createdAt != null ? createdAt.toLocalDateTime() : null
                ));
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }

        return questions;
    }

    public boolean createQuestion(String typeTicket,
                                  String objet,
                                  String description,
                                  String priorite,
                                  String statut,
                                  String fileName,
                                  String filePath,
                                  String fileType,
                                  Integer fileSize,
                                  java.time.LocalDateTime createdAt,
                                  Integer utilisateurId) {
        String sql = "INSERT INTO question (type_ticket, objet, description, priorite, statut, file_name, file_path, file_type, file_size, created_at, "
                + getUserFkColumn() + ") " +
                "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";

        try (Connection conn = DatabaseUtil.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, typeTicket);
            stmt.setString(2, objet);
            stmt.setString(3, description);
            stmt.setString(4, priorite);
            stmt.setString(5, statut);
            stmt.setString(6, fileName);
            stmt.setString(7, filePath);
            stmt.setString(8, fileType);
            if (fileSize == null) {
                stmt.setNull(9, java.sql.Types.INTEGER);
            } else {
                stmt.setInt(9, fileSize);
            }
            stmt.setTimestamp(10, java.sql.Timestamp.valueOf(createdAt));
            if (utilisateurId == null) {
                stmt.setNull(11, java.sql.Types.INTEGER);
            } else {
                stmt.setInt(11, utilisateurId);
            }
            return stmt.executeUpdate() > 0;
        } catch (SQLException e) {
            e.printStackTrace();
        }
        return false;
    }

    public List<Question> getQuestionsByAnswered(boolean answered) {
        List<Question> questions = new ArrayList<>();
        String joinColumn = getResponseQuestionFkColumn();
        String sql = "SELECT q.id_question, q.objet, q.type_ticket, q.priorite, q.statut, q.created_at " +
                "FROM question q " +
                "LEFT JOIN response_question rq ON rq." + joinColumn + " = q.id_question " +
                "WHERE " + (answered ? "rq.id_reponse IS NOT NULL" : "rq.id_reponse IS NULL") + " " +
                "GROUP BY q.id_question " +
                "ORDER BY q.id_question DESC";

        try (Connection conn = DatabaseUtil.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql);
             ResultSet rs = stmt.executeQuery()) {

            while (rs.next()) {
                java.sql.Timestamp createdAt = rs.getTimestamp("created_at");
                questions.add(new Question(
                        rs.getInt("id_question"),
                        rs.getString("objet"),
                        rs.getString("type_ticket"),
                        rs.getString("priorite"),
                        rs.getString("statut"),
                        createdAt != null ? createdAt.toLocalDateTime() : null
                ));
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }

        return questions;
    }

    private String getUserFkColumn() {
        if (userFkColumn != null) {
            return userFkColumn;
        }
        String resolved = "id_utilisateur_id";
        try (Connection conn = DatabaseUtil.getConnection();
             ResultSet rs = conn.getMetaData().getColumns(conn.getCatalog(), null, "question", null)) {
            Set<String> columns = new HashSet<>();
            while (rs.next()) {
                columns.add(rs.getString("COLUMN_NAME").toLowerCase());
            }
            if (columns.contains("id_utilisateur")) {
                resolved = "id_utilisateur";
            }
        } catch (SQLException e) {
            // keep default
        }
        userFkColumn = resolved;
        return userFkColumn;
    }

    private String getResponseQuestionFkColumn() {
        if (responseQuestionFkColumn != null) {
            return responseQuestionFkColumn;
        }
        String resolved = "id_question_id";
        try (Connection conn = DatabaseUtil.getConnection();
             ResultSet rs = conn.getMetaData().getColumns(conn.getCatalog(), null, "response_question", null)) {
            Set<String> columns = new HashSet<>();
            while (rs.next()) {
                columns.add(rs.getString("COLUMN_NAME").toLowerCase());
            }
            if (columns.contains("id_question")) {
                resolved = "id_question";
            }
        } catch (SQLException e) {
            // keep default
        }
        responseQuestionFkColumn = resolved;
        return responseQuestionFkColumn;
    }
}

/* ============================================
   League of Legends Style - Login Page
   ============================================ */

/* Root Background */
.lol-root {
    -fx-background-color: linear-gradient(to bottom right, #1F6F54, #2E8B57);
    -fx-min-width: 900;
    -fx-min-height: 550;
}

/* Floating Background Animation */
.floating-bg {
    -fx-background-color: transparent;
}

.floating-circle {
    -fx-background-color: rgba(255, 255, 255, 0.1);
    -fx-shape: "M50,0 C77.6,0 100,22.4 100,50 C100,77.6 77.6,100 50,100 C22.4,100 0,77.6 0,50 C0,22.4 22.4,0 50,0";
    -fx-min-width: 200;
    -fx-min-height: 200;
    -fx-pref-width: 250;
    -fx-pref-height: 250;
    -fx-opacity: 0;
}

/* Main Card Container */
.lol-card {
    -fx-background-color: white;
    -fx-background-radius: 20;
    -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.4), 30, 0.5, 0, 10);
    -fx-min-width: 850;
    -fx-min-height: 500;
    -fx-max-width: 900;
    -fx-max-height: 550;
}

/* Card Content Container with Clip */
.card-content-container {
    -fx-min-width: 850;
    -fx-min-height: 500;
    -fx-clip-rects: 0 0 850 500;
}

/* Form Panels */
.form-panel-left {
    -fx-background-color: white;
    -fx-min-width: 428;
    -fx-min-height: 500;
    -fx-max-width: 428;
    -fx-max-height: 500;
    -fx-alignment: center;
    -fx-padding: 40;
    -fx-translate-x: 0;
}

.form-panel-right {
    -fx-background-color: white;
    -fx-min-width: 428;
    -fx-min-height: 500;
    -fx-max-width: 428;
    -fx-max-height: 500;
    -fx-alignment: center;
    -fx-padding: 40;
}

/* Sliding Panel - Green Overlay */
.sliding-panel {
    -fx-background-color: #1F6F54;
    -fx-min-width: 422;
    -fx-min-height: 500;
    -fx-alignment: center;
    -fx-padding: 40;
}

/* Titles */
.lol-title {
    -fx-font-size: 36;
    -fx-font-family: "Segoe UI Light", sans-serif;
    -fx-fill: #1a1a1a;
    -fx-font-weight: bold;
}

.lol-subtitle {
    -fx-font-size: 14;
