    -fx-fill: #888;
}

.panel-title {
    -fx-font-size: 32;
    -fx-font-family: "Segoe UI Light", sans-serif;
    -fx-fill: white;
    -fx-font-weight: bold;
}

.panel-subtitle {
    -fx-font-size: 13;
    -fx-font-family: "Segoe UI", sans-serif;
    -fx-fill: rgba(255,255,255,0.8);
}

/* Input Fields */
.lol-input {
    -fx-background-color: #f5f7fa;
    -fx-background-radius: 10;
    -fx-border-radius: 10;
    -fx-padding: 12 15 12 15;
    -fx-font-size: 14;
    -fx-font-family: "Segoe UI", sans-serif;
    -fx-min-height: 42;
    -fx-min-width: 280;
    -fx-prompt-text-fill: #999;
}

.lol-input:focused {
    -fx-background-color: white;
    -fx-border-color: #1F6F54;
    -fx-border-width: 2;
    -fx-border-radius: 10;
}

/* Buttons */
.lol-button-primary {
    -fx-background-color: #1F6F54;
    -fx-background-radius: 20;
    -fx-text-fill: white;
    -fx-font-size: 14;
    -fx-font-family: "Segoe UI Semibold", sans-serif;
    -fx-font-weight: bold;
    -fx-letter-spacing: 2;
    -fx-cursor: hand;
    -fx-min-height: 45;
}

.lol-button-primary:hover {
    -fx-background-color: #258562;
}

.lol-button-primary:pressed {
    -fx-background-color: #1a5c43;
    -fx-scale-x: 0.98;
    -fx-scale-y: 0.98;
}

.lol-button-panel {
    -fx-background-color: transparent;
    -fx-background-radius: 20;
    -fx-border-color: white;
    -fx-border-width: 2;
    -fx-border-radius: 20;
    -fx-text-fill: white;
    -fx-font-size: 14;
    -fx-font-family: "Segoe UI Semibold", sans-serif;
    -fx-font-weight: bold;
    -fx-letter-spacing: 2;
    -fx-cursor: hand;
}

.lol-button-panel:hover {
    -fx-background-color: rgba(255,255,255,0.15);
    -fx-scale-x: 1.05;
    -fx-scale-y: 1.05;
}

.lol-button-panel:pressed {
    -fx-background-color: rgba(255,255,255,0.25);
    -fx-scale-x: 0.98;
    -fx-scale-y: 0.98;
}

/* Link Buttons */
.lol-link-button {
    -fx-background-color: transparent;
    -fx-text-fill: #1F6F54;
    -fx-font-size: 13;
    -fx-font-family: "Segoe UI Semibold", sans-serif;
    -fx-cursor: hand;
    -fx-padding: 0;
}

.lol-link-button:hover {
    -fx-text-fill: #258562;
