    -fx-effect: dropshadow(gaussian, rgba(0,0,0,0.4), 30, 0.5, 0, 10);
    -fx-min-width: 850;
    -fx-min-height: 500;
    -fx-max-width: 900;
    -fx-max-height: 550;
}

/* Card Content Container with Clip */
.card-content-container {
    -fx-min-width: 850;
    -fx-min-height: 500;
    -fx-clip-rects: 0 0 850 500;
}

/* Form Panels */
.form-panel-left {
    -fx-background-color: white;
    -fx-min-width: 428;
    -fx-min-height: 500;
    -fx-max-width: 428;
    -fx-max-height: 500;
