}

/* Small Text */
.lol-text-small {
    -fx-font-size: 13;
    -fx-font-family: "Segoe UI", sans-serif;
    -fx-fill: #666;
}

/* Animation Classes (applied via Java) */
.slide-left-animation {
    /* Used for sliding animation */
}

.fade-animation {
    /* Used for fade transitions */
}

/* Hover effects for inputs */
.text-field:hover, .password-field:hover {
    -fx-background-color: #eef1f5;
}

