.pagination-bar {
    -fx-spacing: 10;
    -fx-alignment: CENTER_RIGHT;
}

/* Message Badge in Navbar */
.message-badge {
    -fx-background-color: #dc3545;
    -fx-text-fill: white;
    -fx-font-size: 10;
    -fx-font-weight: bold;
    -fx-padding: 2 6;
    -fx-background-radius: 10;
    -fx-translate-x: 12;
    -fx-translate-y: -10;
}
